    const originalCompile = ajv.compile.bind(ajv);
    ajv.compile = schema => {
      const validator = originalCompile(schema);
      const legacyValidator = ((input: Record<string, unknown>) => {
        const valid = validator(input);
        if (!valid && validator.errors) {
          (validator.errors[0] as {dataPath?: string; instancePath?: string}).dataPath = (
            validator.errors[0] as {instancePath?: string}
          ).instancePath?.replace(/^\//, '.');
          delete (validator.errors[0] as {instancePath?: string}).instancePath;
        }
        legacyValidator.errors = validator.errors;
        return valid;
      }) as ((input: Record<string, unknown>) => boolean) & {errors?: unknown[]};
      return legacyValidator;
    };
    registry.register(
      () => ({
        name: 'legacy_path',
        description: 'Validate a legacy path',
        inputSchema: {type: 'object', properties: {identifier: {type: 'string'}}, required: ['identifier']},
